//! Generated by LLM (Deepseek)

const std = @import("std");

/// 执行 CPUID 指令，返回 EAX、EBX、ECX、EDX 四个寄存器。
/// 仅支持 x86/x86_64 目标。
pub fn cpuid(eax: u32, ecx: u32) struct { eax: u32, ebx: u32, ecx: u32, edx: u32 } {
    var eax_out: u32 = undefined;
    var ebx_out: u32 = undefined;
    var ecx_out: u32 = undefined;
    var edx_out: u32 = undefined;
    asm volatile ("cpuid"
        : [_] "={eax}" (eax_out),
          [_] "={ebx}" (ebx_out),
          [_] "={ecx}" (ecx_out),
          [_] "={edx}" (edx_out),
        : [_] "{eax}" (eax),
          [_] "{ecx}" (ecx),
        : "memory");
    return .{
        .eax = eax_out,
        .ebx = ebx_out,
        .ecx = ecx_out,
        .edx = edx_out,
    };
}

// ----------------------------------------------------------------------
// Leaf 0 – 获取最大标准叶子和厂商字符串
// ----------------------------------------------------------------------
pub const Leaf0 = struct {
    max_leaf: u32,
    vendor_string: [12]u8,
};

/// 返回 Leaf 0 信息。
pub fn getLeaf0() Leaf0 {
    const r = cpuid(0, 0);
    var vendor: [12]u8 = undefined;
    @memcpy(vendor[0..4], @as(*const [4]u8, @ptrCast(&r.ebx)));
    @memcpy(vendor[4..8], @as(*const [4]u8, @ptrCast(&r.edx)));
    @memcpy(vendor[8..12], @as(*const [4]u8, @ptrCast(&r.ecx)));
    return .{ .max_leaf = r.eax, .vendor_string = vendor };
}

