// ----------------------------------------------------------------------
// 使用示例（可在测试中启用）
// ----------------------------------------------------------------------
test "cpuid leaf1" {
    const leaf1 = getLeaf1();
    std.debug.print("Leaf1: EAX=0x{X:0>8}, EBX=0x{X:0>8}\n", .{ leaf1.eax, leaf1.ebx });
    std.debug.print("  SSE3: {}\n", .{leaf1.ecx.sse3});
    std.debug.print("  AVX:  {}\n", .{leaf1.ecx.avx});
    std.debug.print("  SSE2: {}\n", .{leaf1.edx.sse2});
}

test "cpuid leaf7" {
    const leaf7 = getLeaf7Sub0();
    std.debug.print("Leaf7: EAX=0x{X:0>8}\n", .{leaf7.eax});
    std.debug.print("  AVX2: {}\n", .{leaf7.ebx.avx2});
    std.debug.print("  SMEP: {}\n", .{leaf7.ebx.smep});
}

test "cpuid ext leaf1" {
    const ext = getExtLeaf1();
    std.debug.print("ExtLeaf1: LM (long mode): {}\n", .{ext.edx.lm});
}
